{"policy":"permit (
    principal is Person,
    action == Action::"reviewContract",
    resource is Contract
)
when {
    principal.roles.contains(Role::"Reviewer") &&
    resource.status == ContractStatus::"Draft" &&
    principal.conflictedCounterparties.contains(resource.counterparty)
};

forbid (
    principal is Person,
    action == Action::"reviewContract",
    resource is Contract
)
when {
    resource.status != ContractStatus::"Draft" ||
    !principal.conflictedCounterparties.contains(resource.counterparty)
};

permit (
    principal is Person,
    action == Action::"signContract",
    resource is Signature
)
when {
    principal.roles.contains(Role::"Signatory") &&
    resource.signer == principal &&
    resource.contract.status == ContractStatus::"Reviewed" &&
    principal.delegatedAuthorityTier >= resource.contract.requiredAuthorityTier &&
    principal.conflictedCounterparties.contains(resource.contract.counterparty)
};

forbid (
    principal is Person,
    action == Action::"signContract",
    resource is Signature
)
when {
    principal.delegatedAuthorityTier < resource.contract.requiredAuthorityTier ||
    !principal.conflictedCounterparties.contains(resource.contract.counterparty)
};

